def compute_profile(x, system):
    """Compute observer profile. Time: O(|ι| · T_obs)"""
    cx = system.compress(x)
    return tuple(obs(cx) for obs in system.observers)

def build_certified_predictor(system):
    """Build predictor with correctness certificate. Time: O(|S| · |ι|)"""
    lookup = {}
    for x in system.states:
        profile = tuple(obs(system.compress(x)) for obs in system.observers)
        if profile not in lookup:
            lookup[profile] = system.compress(x)
    return lookup

def build_canonical_tree(compressed, d):
    """Build canonical ultrametric tree. Time: O(n²)"""
    distances = sorted(set(d(a,b) for a in compressed for b in compressed if a != b), reverse=True)
    def partition(states, r):
        clusters, remaining = [], set(states)
        while remaining:
            x = min(remaining)
            cluster = [y for y in remaining if d(x,y) <= r]
            clusters.append(cluster)
            remaining -= set(cluster)
        return clusters
    return {r: partition(compressed, r) for r in distances}
